cat <<'EOF' >> /app/src/user/data.js

	// Private data hiding utility
	User.hidePrivateData = async function (userData, callerUID) {
		// Create a shallow copy to avoid mutation
		const filteredData = { ...userData };

		// If callerUID is invalid/guest, always hide email and fullname
		if (!callerUID || parseInt(callerUID, 10) <= 0) {
			filteredData.email = '';
			filteredData.fullname = '';
			return filteredData;
		}

		const targetUID = userData.uid;

		// If caller is the same user, return full data
		if (parseInt(callerUID, 10) === parseInt(targetUID, 10)) {
			return filteredData;
		}

		// Check if caller has admin or global moderator privileges
		const isAdmin = await User.isAdministrator(callerUID);
		const isGlobalMod = await User.isGlobalModerator(callerUID);

		if (isAdmin || isGlobalMod) {
			return filteredData;
		}

		// Regular user, not the target: apply privacy filtering
		const settings = await User.getSettings(targetUID);

		// Email: hide if user's showemail is false or global hideEmail is enabled
		if (!settings.showemail || meta.config.hideEmail) {
			filteredData.email = '';
		}

		// Fullname: hide if user's showfullname is false or global hideFullname is enabled
		if (!settings.showfullname || meta.config.hideFullname) {
			filteredData.fullname = '';
		}

		return filteredData;
	};
EOF

