  head -n 55 /app/src/controllers/user.js
  cat <<'EOF'
userController.getUserDataByUID = async function (callerUid, uid) {
    if (!parseInt(uid, 10)) {
        throw new Error('[[error:no-user]]');
    }
    const canView = await privileges.global.can('view:users', callerUid);
    if (!canView) {
        throw new Error('[[error:no-privileges]]');
    }
    const userData = await user.getUserData(uid);
    if (!userData) {
        throw new Error('[[error:no-user]]');
    }
    return await user.hidePrivateData(userData, callerUid);
};
EOF
  tail -n +75 /app/src/controllers/user.js
} > /tmp/user.js && mv /tmp/user.js /app/src/controllers/user.js

